const MARKERS = [
  { x: 332, y: 68.8 },
  { x: 362.2, y: 211.6 },
  { x: 630.9, y: 277.3 },
  { x: 243.4, y: 342.9 },
  { x: 393.2, y: 403.2 },
  { x: 358, y: 443.9 },
  { x: 447.4, y: 516.7 },
  { x: 390.3, y: 550.5 },
  { x: 392.1, y: 611.3 },
  { x: 490.4, y: 648.5 },
  { x: 558.4, y: 722.4 },
  { x: 213.6, y: 1103.5 },
  { x: 357, y: 1283 },
];

/**
 * A city skyline under the map: towers in the same hairline as the province outlines, with lit
 * windows coming on one at a time.
 *
 * This is the subject the app is actually about — the condominium buildings it prices are these —
 * and a night skyline gives the sparkle somewhere honest to live: a window lighting up is a thing
 * cities do, so the shimmer is the motif rather than an effect laid over one.
 *
 * Two depths. The far row is shorter and fainter and drifts slowly; the near row is taller and
 * drifts a little faster, which is enough parallax to give the band depth without any of it moving
 * fast enough to catch the eye while someone is reading.
 */
const BAND_W = 1000;
const GROUND_Y = 600;

/**
 * Deterministic noise. Hash rather than Math.random, so every render draws one city rather than a
 * new one on each mount.
 */
function noise(a: number, b: number): number {
  const n = Math.sin(a * 127.1 + b * 311.7) * 43758.5453;
  return n - Math.floor(n);
}

interface Tower {
  readonly x: number;
  readonly w: number;
  readonly h: number;
  /** A mast on the taller towers, the way the ones on Sathon and Rama III carry them. */
  readonly mast: boolean;
  /** A setback near the top, which is what makes a tower read as a tower and not a bar. */
  readonly setback: boolean;
  /** How much narrower the top is than the base, as a fraction of the width. */
  readonly taper: number;
  /** How far the sides bow out on the way up. Small: a lean, not a curve. */
  readonly bow: number;
  /** Flat, domed or slanted crown. */
  readonly roof: "flat" | "dome" | "slant";
}

/**
 * One row of towers, laid out left to right until the band is crossed.
 *
 * The gaps do as much work as the buildings. A row packed edge to edge is a wall with notches in
 * it; leaving sky between the towers is what lets each one read as a building, so the count falls
 * out of the spacing rather than being set directly.
 */
interface RowSpec {
  readonly seed: number;
  readonly minH: number;
  readonly maxH: number;
  readonly minW: number;
  readonly maxW: number;
  readonly minGap: number;
  readonly maxGap: number;
}

function row(spec: RowSpec): Tower[] {
  const towers: Tower[] = [];
  let x = -40;
  for (let i = 0; i < 40 && x < BAND_W + 40; i += 1) {
    const w = spec.minW + noise(i, spec.seed) * (spec.maxW - spec.minW);
    const h = spec.minH + noise(i, spec.seed + 7) * (spec.maxH - spec.minH);
    const roofPick = noise(i, spec.seed + 31);
    towers.push({
      x,
      w,
      h,
      mast: h > spec.maxH * 0.78,
      setback: noise(i, spec.seed + 13) > 0.5,
      taper: 0.06 + noise(i, spec.seed + 41) * 0.12,
      bow: 1.5 + noise(i, spec.seed + 53) * 4,
      roof: roofPick > 0.66 ? "dome" : roofPick > 0.33 ? "slant" : "flat",
    });
    x += w + spec.minGap + noise(i, spec.seed + 21) * (spec.maxGap - spec.minGap);
  }
  return towers;
}

const FAR_TOWERS = row({
  seed: 3,
  minH: 90,
  maxH: 230,
  minW: 48,
  maxW: 100,
  minGap: 34,
  maxGap: 104,
});

const NEAR_TOWERS = row({
  seed: 11,
  minH: 190,
  maxH: 450,
  minW: 62,
  maxW: 122,
  minGap: 86,
  maxGap: 190,
});

/**
 * Lit windows, scattered rather than gridded. A full grid of unlit panes would be hundreds of
 * elements for something nobody looks at; only the lights that are on are drawn, which is also
 * what a city at night actually shows.
 */
function windowsFor(towers: readonly Tower[], seed: number, density: number) {
  const lights: { id: string; x: number; y: number; delay: number; duration: number }[] = [];
  towers.forEach((tower, index) => {
    const columns = Math.max(2, Math.floor(tower.w / 13));
    const rows = Math.max(3, Math.floor(tower.h / 20));
    for (let c = 0; c < columns; c += 1) {
      for (let r = 0; r < rows; r += 1) {
        if (noise(index * 100 + c * 7 + r, seed) > density) {
          continue;
        }
        lights.push({
          id: `${seed}-${index}-${c}-${r}`,
          x: tower.x + 7 + (c * (tower.w - 12)) / Math.max(1, columns - 1 || 1),
          y: GROUND_Y - tower.h + 16 + r * ((tower.h - 24) / Math.max(1, rows - 1 || 1)),
          // Spread across the cycle, and each window keeps its own rate, so the city never blinks
          // in unison — which is the one thing that would read as a screensaver.
          delay: noise(index + c, r + seed) * 7,
          duration: 6 + noise(r + seed, index + c) * 7,
        });
      }
    }
  });
  return lights;
}

// Fewer towers, so each carries far more lit windows: the shimmer stays where the eye expects it.
const FAR_WINDOWS = windowsFor(FAR_TOWERS, 5, 0.34);
const NEAR_WINDOWS = windowsFor(NEAR_TOWERS, 9, 0.42);

/**
 * A tower as a drawn shape rather than a rectangle.
 *
 * Three things do the softening, all of them small. The sides taper, so the top is narrower than
 * the base. They bow outward on the way up by a couple of pixels, so the edge is a line someone
 * drew rather than one a compiler emitted. And the crown is flat, domed or slanted rather than
 * always square. None of it is enough to notice on its own; together they are the difference
 * between a skyline and a bar chart.
 */
function towerPath(tower: Tower): string {
  const top = GROUND_Y - tower.h;
  const inset = tower.w * tower.taper;
  const lx = tower.x;
  const rx = tower.x + tower.w;
  const ltx = lx + inset;
  const rtx = rx - inset;

  // Control points sit at a third and two thirds of the height, pushed out by the bow.
  const c1 = GROUND_Y - tower.h * 0.34;
  const c2 = GROUND_Y - tower.h * 0.7;
  const leftSide = `C ${lx - tower.bow} ${c1}, ${ltx - tower.bow} ${c2}, ${ltx} ${top}`;
  const rightSide = `C ${rtx + tower.bow} ${c2}, ${rx + tower.bow} ${c1}, ${rx} ${GROUND_Y}`;

  const crown =
    tower.roof === "dome"
      ? `Q ${(ltx + rtx) / 2} ${top - tower.h * 0.045}, ${rtx} ${top}`
      : tower.roof === "slant"
        ? `L ${rtx} ${top + tower.h * 0.035}`
        : `L ${rtx} ${top}`;

  if (!tower.setback) {
    return `M ${lx} ${GROUND_Y} ${leftSide} ${crown} ${rightSide} Z`;
  }

  // With a setback the shaft stops at the shoulder and a narrower crown continues above it.
  const shoulder = top + tower.h * 0.16;
  const step = tower.w * 0.15;
  return (
    `M ${lx} ${GROUND_Y} C ${lx - tower.bow} ${c1}, ${ltx - tower.bow} ${c2}, ${ltx} ${shoulder} ` +
    `L ${ltx + step} ${shoulder} L ${ltx + step} ${top} ` +
    `${tower.roof === "dome" ? `Q ${(ltx + rtx) / 2} ${top - tower.h * 0.04}, ${rtx - step} ${top}` : `L ${rtx - step} ${top}`} ` +
    `L ${rtx - step} ${shoulder} L ${rtx} ${shoulder} ` +
    `C ${rtx + tower.bow} ${c2}, ${rx + tower.bow} ${c1}, ${rx} ${GROUND_Y} Z`
  );
}

function SkylineRow({
  towers,
  windows,
  className,
}: {
  towers: readonly Tower[];
  windows: readonly { id: string; x: number; y: number; delay: number; duration: number }[];
  className: string;
}) {
  return (
    <g className={className}>
      {towers.map((tower) => (
        <g key={tower.x}>
          <path className="terrain-tower" d={towerPath(tower)} vectorEffect="non-scaling-stroke" />
          {tower.mast && (
            <path
              className="terrain-mast"
              d={`M ${tower.x + tower.w / 2} ${GROUND_Y - tower.h - (tower.roof === "dome" ? tower.h * 0.045 : 0)} L ${tower.x + tower.w / 2} ${GROUND_Y - tower.h - 28}`}
              vectorEffect="non-scaling-stroke"
            />
          )}
        </g>
      ))}
      {windows.map((light) => (
        <rect
          key={light.id}
          className="terrain-window"
          x={light.x}
          y={light.y}
          width="3"
          height="4"
          style={{
            animationDelay: `${light.delay}s`,
            animationDuration: `${light.duration}s`,
          }}
        />
      ))}
    </g>
  );
}

/**
 * Drizzle. Sparse and slow, because ฝนปรอย is not a downpour: 26 streaks over the whole viewport,
 * each thin enough to read as a hint of rain rather than as lines drawn across the screen.
 *
 * Generated from the same hash as everything else here, so the rain falls the same way on every
 * render. A drift value leans each streak, which is what stops rain from looking like it is falling
 * in a vacuum.
 */
const DRIZZLE = Array.from({ length: 26 }, (_, i) => ({
  id: i,
  left: (noise(i, 71) * 104 - 2).toFixed(2),
  length: 16 + noise(i, 83) * 28,
  delay: noise(i, 97) * 9,
  duration: 2.4 + noise(i, 109) * 2.6,
  drift: 14 + noise(i, 127) * 26,
  // The stroke token is already low-alpha, so a further 0.2 multiplier left the rain invisible.
  opacity: 0.45 + noise(i, 139) * 0.5,
}));

export function TerrainBackdrop() {
  return (
    <div className="terrain" aria-hidden="true">
      <div className="terrain-wash" />

      <div className="terrain-pattern">
        <svg
          className="terrain-svg terrain-map"
          viewBox="0 0 1000 1400"
          preserveAspectRatio="xMidYMid meet"
        >
          <title>แผนที่ประเทศไทยประกอบการตกแต่ง</title>
          <g className="terrain-map-shapes">
            {PROVINCES.map((d, i) => (
              // biome-ignore lint/suspicious/noArrayIndexKey: decorative outlines have no identity
              <path key={i} d={d} style={{ animationDelay: `${(i % 12) * 0.4}s` }} />
            ))}
          </g>

          <g className="terrain-markers">
            {MARKERS.map((m, i) => (
              // biome-ignore lint/suspicious/noArrayIndexKey: decorative markers have no identity
              <g key={i} style={{ animationDelay: `${i * 0.75}s` }}>
                <circle className="terrain-marker-dot" cx={m.x} cy={m.y} r="5" />
                <circle className="terrain-marker-halo" cx={m.x} cy={m.y} r="5" />
              </g>
            ))}
          </g>
        </svg>

        <div className="terrain-sweep" />
      </div>

      <div className="terrain-canopy-wrap">
        <svg
          className="terrain-svg terrain-canopy"
          viewBox="0 0 1000 600"
          preserveAspectRatio="none"
        >
          <title>เส้นขอบฟ้าเมืองประกอบการตกแต่ง</title>
          <SkylineRow towers={FAR_TOWERS} windows={FAR_WINDOWS} className="terrain-skyline-far" />
          <SkylineRow
            towers={NEAR_TOWERS}
            windows={NEAR_WINDOWS}
            className="terrain-skyline-near"
          />
        </svg>
      </div>

      <div className="terrain-drizzle">
        {DRIZZLE.map((drop) => (
          <span
            key={drop.id}
            className="terrain-drop"
            style={
              {
                left: `${drop.left}%`,
                height: `${drop.length}px`,
                animationDelay: `${drop.delay}s`,
                animationDuration: `${drop.duration}s`,
                opacity: drop.opacity,
                "--drop-drift": `${drop.drift}px`,
              } as React.CSSProperties
            }
          />
        ))}
      </div>
    </div>
  );
}
